{
  "tool": "edit_file",
  "args": {
    "path": "code/benchmark_analysis_nn.py",
    "old_str": "    # Save results
    os.makedirs('outputs', exist_ok=True)
    with open('outputs/results.json', 'w') as f:
        # Convert numpy arrays to lists for JSON serialization
        results_json = []
        for r in results:
            r_copy = r.copy()
            r_copy['y_test'] = r_copy['y_test'].tolist()
            r_copy['y_pred'] = r_copy['y_pred'].tolist()
            results_json.append(r_copy)
        json.dump(results_json, f, indent=2)",
    "new_str": "    # Save results
    os.makedirs('outputs', exist_ok=True)
    with open('outputs/results.json', 'w') as f:
        # Convert numpy arrays to lists for JSON serialization
        results_json = []
        for r in results:
            r_copy = {}
            for k, v in r.items():
                if k in ['y_test', 'y_pred']:
                    r_copy[k] = [int(x) for x in v]
                elif isinstance(v, np.integer):
                    r_copy[k] = int(v)
                elif isinstance(v, np.floating):
                    r_copy[k] = float(v)
                elif isinstance(v, np.ndarray):
                    r_copy[k] = v.tolist()
                else:
                    r_copy[k] = v
            results_json.append(r_copy)
        json.dump(results_json, f, indent=2)"
  }
}
